//
// Assembler corpus parity test: each program in data/golden/asm/corpus must
// produce the same listing (.L68) and S-records (.S68) as the ORIGINAL
// EASy68K assembler, for each option variant. The expected files are
// generated by the reference oracle (tools/reference/regenerate_corpus.sh).
// The corpus covers directives, macros, conditional and structured assembly,
// OPT/listing control, INCLUDE/INCBIN, MEMORY, local labels, editor tab
// settings and error/warning paths.

#include <gtest/gtest.h>

#include <algorithm>
#include <filesystem>
#include <fstream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

#include "easym68k/asm/assembler.h"

namespace easym68k::asm_ {
namespace {

std::filesystem::path CorpusDir() {
  std::filesystem::path p = std::filesystem::current_path();
  for (int i = 0; i < 5; ++i) {
    if (std::filesystem::exists(p / "data" / "golden" / "asm" / "corpus"))
      return p / "data" / "golden" / "asm" / "corpus";
    p = p.parent_path();
  }
  return "data/golden/asm/corpus";
}

std::string ReadFile(const std::filesystem::path& path) {
  std::ifstream f(path, std::ios::binary);
  std::ostringstream ss;
  ss << f.rdbuf();
  return ss.str();
}

std::string StripCr(const std::string& s) {
  std::string out;
  for (char c : s)
    if (c != '\r')
      out.push_back(c);
  return out;
}

struct Variant {
  const char* name;
  AssemblerOptions options;
};

std::vector<Variant> Variants() {
  AssemblerOptions def;
  AssemblerOptions expand;
  expand.mex = expand.sex = expand.cex = true;
  AssemblerOptions nocre;
  nocre.cre = nocre.warnings = nocre.bitfield = false;
  return {{"default", def}, {"expand", expand}, {"nocre", nocre}};
}

struct Case {
  std::string program;
  std::string variant;
};

std::vector<Case> Cases() {
  std::vector<std::string> programs;
  std::error_code ec;
  for (const auto& e : std::filesystem::directory_iterator(CorpusDir(), ec)) {
    std::string name = e.path().filename().string();
    if (e.path().extension() == ".x68" && name.rfind("inc_", 0) != 0)
      programs.push_back(e.path().stem().string());
  }
  std::sort(programs.begin(), programs.end());
  std::vector<Case> cases;
  for (const auto& p : programs)
    for (const auto& v : Variants())
      cases.push_back({p, v.name});
  return cases;
}

// Memory image of S1/S2/S3 records, bytes equal to $FF omitted (the value of
// erased Sim68K memory).
std::map<uint32_t, uint8_t> SRecordImage(const std::string& srec) {
  std::map<uint32_t, uint8_t> image;
  std::istringstream in(srec);
  std::string line;
  while (std::getline(in, line)) {
    if (line.size() < 4 || line[0] != 'S' || line[1] < '1' || line[1] > '3')
      continue;
    int addr_len = 2 * (line[1] - '0' + 1);
    int count = std::stoi(line.substr(2, 2), nullptr, 16);
    uint32_t addr = static_cast<uint32_t>(std::stoul(line.substr(4, addr_len), nullptr, 16));
    int data_bytes = count - addr_len / 2 - 1;
    for (int i = 0; i < data_bytes; i++) {
      auto b = static_cast<uint8_t>(std::stoi(line.substr(4 + addr_len + 2 * i, 2), nullptr, 16));
      if (b != 0xFF)
        image[addr + i] = b;
      else
        image.erase(addr + i);
    }
  }
  return image;
}

class CorpusTest : public ::testing::TestWithParam<Case> {};

TEST_P(CorpusTest, MatchesOriginalAssembler) {
  const Case& c = GetParam();
  const std::filesystem::path dir = CorpusDir();
  AssemblerOptions options;
  for (const auto& v : Variants())
    if (c.variant == v.name)
      options = v.options;

  Assembler assembler;
  assembler.SetOptions(options);
  assembler.ConfigureListing((dir / (c.program + ".x68")).string(), "", 60, options.cex);
  assembler.SetFileReader([&dir](const std::string& name) { return ReadFile(dir / name); });
  AssemblyResult r = assembler.Assemble(ReadFile(dir / (c.program + ".x68")));

  const std::filesystem::path expected = dir / "expected" / c.variant;
  EXPECT_EQ(StripCr(assembler.GetListing()), StripCr(ReadFile(expected / (c.program + ".L68"))))
      << "listing differs for " << c.program << " (" << c.variant << ")";
  const std::string want = StripCr(ReadFile(expected / (c.program + ".S68")));
  const std::string got = StripCr(r.srecord);
  if (got != want && ReadFile(dir / (c.program + ".x68")).find("SIMHALT") != std::string::npos) {
    // SIMHALT: the original writes only one of its two $FFFF words to the
    // S-records (deviation, fixed in the port), which also shifts the record
    // splitting. Compare the loaded images instead (Sim68K erases memory to
    // $FF before loading) plus the header and end records.
    EXPECT_EQ(SRecordImage(got), SRecordImage(want)) << c.program << " (" << c.variant << ")";
    EXPECT_EQ(got.substr(0, got.find('\n')), want.substr(0, want.find('\n')));
    EXPECT_EQ(got.substr(got.rfind("S8")), want.substr(want.rfind("S8")));
  } else {
    EXPECT_EQ(got, want) << "S-records differ for " << c.program << " (" << c.variant << ")";
  }
}

INSTANTIATE_TEST_SUITE_P(Corpus, CorpusTest, ::testing::ValuesIn(Cases()),
                         [](const ::testing::TestParamInfo<Case>& info) {
                           return info.param.program + "_" + info.param.variant;
                         });

}  // namespace
}  // namespace easym68k::asm_
